// /app/app/component-poll.js — the shared component poll scheduler
// (launch-readiness roadmap item 3, 2026-08-15).
//
// Before this module, ~25 components each owned a private setInterval, most
// with a copy-pasted _setIntervalUnref helper and no visibility handling:
// a hidden tab kept every panel polling the APIs and RPC forever. This
// scheduler gives every component timer the same discipline polling.js gives
// its own four cycles:
//
//   - hidden tab  → every registered poll STOPS (zero background traffic);
//   - visible     → catch up in small batches after the primary state refresh,
//                   then re-arm on each poll's normal interval;
//   - unregister  → idempotent, safe in disconnectedCallback.
//   - off page    → on the phone section pager, a poll whose owner sits on a
//                   page that is not showing ticks at most every two minutes
//                   and catches up the moment its page is shown.
//
// Registration does NOT fire the callback up front — components keep their
// existing mount-time refresh call. Each registration is single-flight: ticks
// that arrive while an async refresh is running collapse into one trailing
// refresh instead of stacking duplicate RPC/API work behind a slow endpoint.

import {
  isMajorDrawActive,
  subscribeMajorDrawActivity,
} from './major-draw-activity.js';
import { isComponentOffPage } from './mobile-page-visibility.js';

const entries = new Set();
let listening = false;
let drawUnsubscribe = null;
let resumeTimer = null;
let resumeQueue = [];
// Let polling.js refresh primary state at 100ms, then give input/paint a turn
// between small groups of background panels. A minimized tab must not resume
// every panel synchronously inside the same visibility event.
const RESUME_DELAY_MS = 250;
const RESUME_BATCH_MS = 125;
const RESUME_BATCH_SIZE = 4;

function cancelResume() {
  if (resumeTimer != null) clearTimeout(resumeTimer);
  resumeTimer = null;
  resumeQueue = [];
}

function resumeBatch() {
  resumeTimer = null;
  if (isPaused()) { cancelResume(); return; }
  for (let i = 0; i < RESUME_BATCH_SIZE && resumeQueue.length > 0; i += 1) {
    const entry = resumeQueue.shift();
    if (!entries.has(entry)) continue;
    run(entry);
    arm(entry);
  }
  if (resumeQueue.length > 0) {
    resumeTimer = setTimeout(resumeBatch, RESUME_BATCH_MS);
    resumeTimer?.unref?.();
  }
}

// ⛔ Phones show one pager page at a time (mobile-pager.js); the rest are display:none but stay
// mounted, so every panel kept polling at full rate. On Ethereum Sepolia's free RPCs that load got
// the page rate-limited (2026-10-16). Off-page panels still tick occasionally rather than not at
// all: several publish Pending-dock actions (claims, settled bets) that must surface from any page.
const OFF_PAGE_MIN_MS = 120_000;

function onPageChange() {
  if (isPaused()) return;
  for (const entry of entries) {
    if (entry.missed && !isComponentOffPage(entry.owner)) {
      entry.missed = false;
      run(entry);
    }
  }
}

function isHidden() {
  return typeof document !== 'undefined' && document.visibilityState === 'hidden';
}

function isPaused() {
  return isHidden() || isMajorDrawActive();
}

function run(entry) {
  if (!entries.has(entry) || isPaused()) return;
  if (entry.owner && isComponentOffPage(entry.owner)) {
    if (Date.now() - entry.lastRunAt < Math.max(OFF_PAGE_MIN_MS, entry.intervalMs * 4)) {
      entry.missed = true;
      return;
    }
  }
  entry.missed = false;
  entry.lastRunAt = Date.now();
  if (entry.running) {
    entry.trailing = true;
    return;
  }
  entry.running = true;
  let result;
  try { result = entry.fn(); }
  catch (_e) { result = undefined; }
  Promise.resolve(result).catch(() => {
    // Components own their presentation/error policy. Consuming the rejection
    // here prevents an otherwise-handled poll from becoming an unhandled one.
  }).finally(() => {
    entry.running = false;
    if (!entries.has(entry) || isPaused()) {
      entry.trailing = false;
      return;
    }
    if (entry.trailing) {
      entry.trailing = false;
      run(entry);
    }
  });
}

// Same-interval polls fire on one shared per-session grid rather than at their
// individual registration/resume phases. A dozen panels poll /player/:addr on
// their own 30s timers; spread across the window, each tick misses api.js's 1s
// in-flight/recent window and pays its own request. Landing them in one burst
// collapses identical URLs to a single request, and chain reads issued in the
// same burst batch into one Multicall3 aggregate (read-provider's ~20ms
// stall window). The grid offset is random per page load, so separate clients
// stay spread and the origin sees no cross-client herd.
const SESSION_PHASE_MS = Math.floor(Math.random() * 2_147_483_647);

function alignedFirstDelay(intervalMs) {
  const remainder = (Date.now() + SESSION_PHASE_MS) % intervalMs;
  let delay = intervalMs - remainder;
  // A boundary landing right after registration would fire a near-immediate
  // tick on top of the component's own mount-time refresh. Sliding one grid
  // step keeps the phase and preserves "registration does not fire up front".
  if (delay < intervalMs / 4) delay += intervalMs;
  return delay;
}

function arm(entry) {
  if (entry.timer != null || isPaused()) return;
  // First tick via setTimeout onto the aligned grid, then a plain interval.
  // setTimeout and setInterval share one handle map (HTML spec; Node's
  // clearInterval also cancels a Timeout), so disarm() cancels either phase.
  entry.timer = setTimeout(() => {
    run(entry);
    if (!entries.has(entry) || isPaused()) { entry.timer = null; return; }
    entry.timer = setInterval(() => run(entry), entry.intervalMs);
    if (entry.timer && typeof entry.timer.unref === 'function') entry.timer.unref();
  }, alignedFirstDelay(entry.intervalMs));
  // Node (tests) returns a Timeout with unref; browsers return a number.
  if (entry.timer && typeof entry.timer.unref === 'function') entry.timer.unref();
}

function disarm(entry) {
  if (entry.timer == null) return;
  clearInterval(entry.timer);
  entry.timer = null;
}

function onVisibilityChange() {
  if (isPaused()) {
    cancelResume();
    for (const entry of entries) {
      disarm(entry);
      entry.trailing = false;
    }
    return;
  }
  // Duplicate visible events must not restart the catch-up or refresh already
  // armed panels again. Hidden registration and paused panels are unarmed.
  if (resumeTimer != null) return;
  resumeQueue = [...entries].filter((entry) => entry.timer == null);
  if (resumeQueue.length === 0) return;
  resumeTimer = setTimeout(resumeBatch, RESUME_DELAY_MS);
  resumeTimer?.unref?.();
}

function onMajorDrawActivity(active) {
  if (active) {
    cancelResume();
    for (const entry of entries) {
      disarm(entry);
      // A tick that arrived behind an in-flight request must not burst into
      // the draw when that request settles.
      entry.trailing = false;
    }
    return;
  }
  // Resume from a fresh interval. An immediate catch-up here would simply
  // move the deferred work into the final reel/scratch handoff.
  for (const entry of entries) arm(entry);
}

function ensureListener() {
  if (!drawUnsubscribe) drawUnsubscribe = subscribeMajorDrawActivity(onMajorDrawActivity);
  if (!listening && typeof document !== 'undefined'
    && typeof document.addEventListener === 'function') {
    listening = true;
    document.addEventListener('visibilitychange', onVisibilityChange);
    document.addEventListener('mobile-pager:change', onPageChange);
    document.addEventListener('desktop-sections:change', onPageChange);
    document.addEventListener('desktop-info:change', onPageChange);
  }
}

/**
 * Register a repeating poll. Returns an idempotent unregister function.
 * Call from connectedCallback; call the returned fn from disconnectedCallback.
 * `owner` (the component element) lets the poll slow down while the phone
 * pager shows another page.
 */
export function registerComponentPoll(fn, intervalMs, { owner = null } = {}) {
  if (typeof fn !== 'function' || !Number.isFinite(intervalMs) || intervalMs <= 0) {
    return () => {};
  }
  ensureListener();
  // lastRunAt starts at registration: the component's own mount-time refresh just ran.
  const entry = { fn, intervalMs, owner, timer: null, running: false, trailing: false, missed: false, lastRunAt: Date.now() };
  entries.add(entry);
  arm(entry);
  return () => {
    if (!entries.has(entry)) return;
    disarm(entry);
    entry.trailing = false;
    entries.delete(entry);
  };
}

/** Test hooks. */
export function _componentPollStatsForTests() {
  let armed = 0;
  for (const entry of entries) if (entry.timer != null) armed++;
  return { registered: entries.size, armed };
}
export function _resetComponentPollsForTests() {
  cancelResume();
  for (const entry of entries) disarm(entry);
  entries.clear();
  try { drawUnsubscribe?.(); } catch (_e) { /* defensive */ }
  drawUnsubscribe = null;
}
export const _onVisibilityChangeForTests = onVisibilityChange;
export const _onPageChangeForTests = onPageChange;
